    # The bottom row encodes the ordered sequence, with zeroes separating
    # its two portions.
    seq = [v for v in grid[-1] if v != 0]
    if not seq:
        return out

    # Each isolated colored marker starts a copy of the sequence, aligned
    # so the marker's color remains in its original cell.
    for r in range(h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0 or color not in seq:
                continue
            k = seq.index(color)
            start = c - k
            for i, v in enumerate(seq):
                x = start + i
                if 0 <= x < w:
                    out[r][x] = v
    return out
